using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class B3RepairSurvey {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B3_StructureRepair/";static string O=>R+"/Docs/Review/2026-11-09_B3_StructureRepair/";
 static Scene Check(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B3_Circular.unity"))throw new Exception("Saved B3 edit scene required; do not switch user scene");return s;}
 public static object Before(){var s=Check();Directory.CreateDirectory(O);if(File.Exists(H+"state_before.json"))throw new Exception("Baseline already captured");if(!File.Exists(H+"scene_before.unity")){File.Copy(s.path,H+"scene_before.unity");File.Copy(s.path+".meta",H+"scene_before.unity.meta");}else if(!File.ReadAllBytes(s.path).SequenceEqual(File.ReadAllBytes(H+"scene_before.unity")))throw new Exception("B3 changed since prepared backup");var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var state=all.Select(t=>new{id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),name=t.name,path=AnimationUtility.CalculateTransformPath(t,null),pos=new[]{t.localPosition.x,t.localPosition.y,t.localPosition.z},rot=new[]{t.localRotation.x,t.localRotation.y,t.localRotation.z,t.localRotation.w},scale=new[]{t.localScale.x,t.localScale.y,t.localScale.z},active=t.gameObject.activeSelf,colliders=t.GetComponents<Collider>().Select(c=>new{type=c.GetType().Name,c.enabled,mesh=c is MeshCollider mc?AssetDatabase.GetAssetPath(mc.sharedMesh):null}),mesh=t.GetComponent<MeshFilter>()?AssetDatabase.GetAssetPath(t.GetComponent<MeshFilter>().sharedMesh):null}).ToArray();File.WriteAllText(H+"state_before.json",JsonConvert.SerializeObject(state,Formatting.Indented));Capture("before");return new{objects=all.Length,scene=s.path,saved=!s.isDirty};}
 static void Shot(string file,Vector3 pos,Vector3 at){var go=new GameObject("B3_RepairInspectionCamera"){hideFlags=HideFlags.HideAndDontSave};var c=go.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(at);c.fieldOfView=85;c.nearClipPlane=.06f;c.farClipPlane=250;c.useOcclusionCulling=false;var l=go.AddComponent<Light>();l.type=LightType.Point;l.intensity=1.2f;l.range=14;l.color=new Color(.85f,.90f,1);var rt=new RenderTexture(1440,900,24){antiAliasing=4};var old=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,900),0,0);tex.Apply();File.WriteAllBytes(O+file+".png",tex.EncodeToPNG());}finally{RenderTexture.active=old;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object After(){Check();Capture("after");return new{images=8};}
 static void Capture(string prefix){Shot(prefix+"_C04_junction",new Vector3(11,-47.3f,-12.8f),new Vector3(22,-47.3f,-15));Shot(prefix+"_C03_junction",new Vector3(-18,-47.3f,-18),new Vector3(-29,-47.3f,-20));var ids=new[]{"C01","C04","W01","W02","N01","S01"};var plan=Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText(R+"/SourceAssets/B3_FullFloor/layout.json"));foreach(string id in ids){var r=plan["rooms"].Single(x=>(string)x["id"]==id);var d=r["doors"][0];var center=new Vector3((float)r["x"],-49,-(float)r["v"]);var dir=new Vector3((float)d["x"],0,(float)d["z"]).normalized;Shot(prefix+"_"+id,center+dir*((float)r["r"]-1.5f)+Vector3.up*2.1f,center+Vector3.up*1.3f);}}
}
